From 06d759f4229229c9869a1056a808d72eeab943df Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:31:10 +0100
Subject: [PATCH] kcm, applet: show readable text for Bluetooth connection
 errors

When connecting failed, the KCM showed BlueZ's raw failure reason, like
"br-connection-create-socket", and the applet's notification only said
that the connection failed. Both now map BlueZ's reasons to plain text.

BUG: 467122
---
 src/applet/devicesstateproxymodel.cpp  | 10 ++--
 src/applet/utils.cpp                   | 63 ++++++++++++++++++++++++++
 src/applet/utils.h                     |  4 ++
 src/kcm/ui/Device.qml                  |  3 +-
 src/kcm/ui/DeviceConnectionSidebar.qml |  3 +-
 src/kcm/ui/main.qml                    |  2 +-
 6 files changed, 79 insertions(+), 6 deletions(-)

diff --git a/src/applet/devicesstateproxymodel.cpp b/src/applet/devicesstateproxymodel.cpp
index e00ffab6..fda8eb0d 100644
--- a/src/applet/devicesstateproxymodel.cpp
+++ b/src/applet/devicesstateproxymodel.cpp
@@ -6,6 +6,7 @@
 */

 #include "devicesstateproxymodel.h"
+#include "utils.h"

 #include <BluezQt/DevicesModel>

@@ -297,11 +298,14 @@ void DevicesStateProxyModel::notifyIfConnectionFailed(const BluezQt::PendingCall

 QString DevicesStateProxyModel::errorText(const BluezQt::PendingCall *call)
 {
+    const QString text = Utils::connectionErrorText(call->errorText());
+    if (!text.isEmpty()) {
+        return text;
+    }
+
     switch (call->error()) {
     case BluezQt::PendingCall::Failed:
-        return call->errorText() == QStringLiteral("Host is down")
-            ? i18nc("Notification when the connection failed due to Failed:HostIsDown", "The device is unreachable")
-            : i18nc("Notification when the connection failed due to Failed", "Connection to the device failed");
+        return i18nc("Notification when the connection failed due to Failed", "Connection to the device failed");

     case BluezQt::PendingCall::NotReady:
         return i18nc("Notification when the connection failed due to NotReady", "The device is not ready");
