     return ubi.mid(startIndex, endIndex - startIndex);
 }

+// Returns a readable text for the error of a finished call, or BlueZ's own text if there is none
+QString Utils::errorText(BluezQt::PendingCall *call)
+{
+    const QString text = connectionErrorText(call->errorText());
+    return text.isEmpty() ? call->errorText() : text;
+}
+
+// Returns a readable text for a BlueZ connection failure reason, or an empty string if it is unknown
+QString Utils::connectionErrorText(const QString &reason)
+{
+    if (reason == QLatin1String("Host is down")) {
+        return i18nc("Notification when the connection failed due to Failed:HostIsDown", "The device is unreachable");
+    }
+    if (reason == QLatin1String("br-connection-already-connected") || reason == QLatin1String("le-connection-already-connected")) {
+        return i18nc("@info:status Bluetooth connection error", "The device is already connected");
+    }
+    if (reason == QLatin1String("br-connection-page-timeout") || reason == QLatin1String("br-connection-timeout")
+        || reason == QLatin1String("le-connection-timeout")) {
+        return i18nc("@info:status Bluetooth connection error", "The device did not respond. Make sure it is turned on and in range.");
+    }
+    if (reason == QLatin1String("br-connection-create-socket") || reason == QLatin1String("le-connection-create-socket")
+        || reason == QLatin1String("br-connection-bad-socket") || reason == QLatin1String("le-connection-bad-socket")) {
+        return i18nc("@info:status Bluetooth connection error", "The connection could not be set up. Make sure the device is turned on and in range.");
+    }
+    if (reason == QLatin1String("br-connection-sdp-search") || reason == QLatin1String("le-connection-gatt-browsing")) {
+        return i18nc("@info:status Bluetooth connection error", "Could not read the services offered by the device");
+    }
+    if (reason == QLatin1String("br-connection-not-supported") || reason == QLatin1String("le-connection-not-supported")) {
+        return i18nc("@info:status Bluetooth connection error", "The device does not offer any service that can be connected to");
+    }
+    if (reason == QLatin1String("br-connection-adapter-not-powered") || reason == QLatin1String("le-connection-adapter-not-powered")) {
+        return i18nc("@info:status Bluetooth connection error", "Bluetooth is turned off");
+    }
+    if (reason == QLatin1String("br-connection-busy") || reason == QLatin1String("le-connection-busy")) {
+        return i18nc("@info:status Bluetooth connection error", "The device or the Bluetooth adapter is busy");
+    }
+    if (reason == QLatin1String("br-connection-concurrent-connection-limit") || reason == QLatin1String("le-connection-concurrent-connection-limit")) {
+        return i18nc("@info:status Bluetooth connection error", "Too many devices are being connected at the same time");
+    }
+    if (reason == QLatin1String("br-connection-refused") || reason == QLatin1String("le-connection-refused")) {
+        return i18nc("@info:status Bluetooth connection error", "The device refused the connection");
+    }
+    if (reason == QLatin1String("br-connection-aborted-by-remote") || reason == QLatin1String("le-connection-abort-by-remote")) {
+        return i18nc("@info:status Bluetooth connection error", "The device closed the connection");
+    }
+    if (reason == QLatin1String("br-connection-aborted-by-local") || reason == QLatin1String("le-connection-abort-by-local")
+        || reason == QLatin1String("br-connection-canceled")) {
+        return i18nc("@info:status Bluetooth connection error", "The connection attempt was canceled");
+    }
+    if (reason == QLatin1String("br-connection-key-missing") || reason == QLatin1String("le-connection-key-missing")) {
+        return i18nc("@info:status Bluetooth connection error", "The device no longer recognizes this computer. Forget the device and pair it again.");
+    }
+    if (reason == QLatin1String("br-connection-invalid-argument") || reason == QLatin1String("le-connection-invalid-arguments")
+        || reason == QLatin1String("br-connection-memory-allocation") || reason == QLatin1String("le-connection-memory-allocation")
+        || reason == QLatin1String("br-connection-lmp-protocol-error") || reason == QLatin1String("le-connection-link-layer-protocol-error")
+        || reason == QLatin1String("br-connection-unknown") || reason == QLatin1String("le-connection-unknown")) {
+        return i18nc("Notification when the connection failed due to Failed", "Connection to the device failed");
+    }
+    return QString();
+}
+
 #include "moc_utils.cpp"
